export type OpenOptions = {
	port: number;
	url: string;
	urlExplicit: boolean;
	userDataDir?: string;
	clean: boolean;
	/** Wait this long for the first tab to load; 0 skips the check. */
	loadTimeoutMs: number;
	session?: string;
	binary?: string;
	headless: boolean;
	status: boolean;
	minimize: boolean;
	/** Below every other window, hidden from the taskbar (the default), instead of minimized. */
	park: boolean;
	flash: boolean;
	dryRun: boolean;
	json: boolean;
	loadExtension?: string;
	/** Keep extensions already installed in the profile (a managed blocker, say). Off by default. */
	keepExtensions: boolean;
	android: boolean;
	record: boolean;
	recordFrames: number | null;
	browserArgs: string[];
	locale: string;
};

type OpenPlan = {
	requestedPort: number;
	actualPort: number;
	browserAction: "launch-new-browser" | "attach-existing-browser";
	portNote: string;
	lockStatus: "none" | "active" | "stale-cleared";
};

type KWinStartupMinimizeHandle = {
	dispose: () => Promise<void>;
};

