export type OpenOptions = {
	port: number;
	url: string;
	urlExplicit: boolean;
	userDataDir?: string;
	clean: boolean;
	/** Wait this long for the first tab to load; 0 skips the check. */
	loadTimeoutMs: number;
	session?: string;
	binary?: string;
	headless: boolean;
	status: boolean;
	minimize: boolean;
	/** Below every other window, hidden from the taskbar (the default), instead of minimized. */
	park: boolean;
	flash: boolean;
