export function extensionArgs(
	options: Pick<
		OpenOptions,
		"loadExtension" | "keepExtensions" | "headless" | "selectorDir"
	>,
): string[] {
	const dirs = [options.loadExtension, options.selectorDir].filter(
		(dir): dir is string => Boolean(dir),
	);
	const args: string[] = [];
	if (dirs.length) args.push(`--load-extension=${dirs.join(",")}`);
	if (options.keepExtensions) return args;
	if (dirs.length) args.push(`--disable-extensions-except=${dirs.join(",")}`);
	else if (options.headless) args.push("--disable-extensions");
	return args;
}

/**
 * Dev Selector is built into `<repo>/.output/chrome-mv3` (or `-dev`). Pick the
 * build with the newest manifest so `--dev-selector` never needs a path.
 */
export function resolveDevSelectorDir(root: string): string {
	const candidates = ["chrome-mv3", "chrome-mv3-dev"].map((name) =>
		join(root, ".output", name),
	);
	let best: { dir: string; mtime: number } | null = null;
	for (const dir of candidates) {
		const manifest = join(dir, "manifest.json");
		if (!existsSync(manifest)) continue;
		const mtime = statSync(manifest).mtimeMs;
		if (!best || mtime > best.mtime) best = { dir, mtime };
	}
	if (!best) {
		throw new Error(
			`No Dev Selector build found: expected ${candidates[0]} or ${candidates[1]} (build it first)`,
		);
	}
	return best.dir;
}

